/**
 * Test flow for Service Catalog trigger
 * Tests: Service catalog request item trigger with all request item outputs
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testServiceCatalogTrigger = Flow(
    {
        $id: Now.ID['test_service_catalog_trigger_flow'],
        name: 'Test Service Catalog Trigger',
        description: 'Tests the Service Catalog trigger for request items',
    },
    wfa.trigger(
        trigger.application.serviceCatalog,
        { $id: Now.ID['test_service_catalog_trigger'] },
        {
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        // Log service catalog request details
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_service_catalog_log'] },
            {
                log_level: 'info',
                log_message: `Service Catalog - Request Item: ${wfa.dataPill(_params.trigger.request_item, 'string')}, Table: ${wfa.dataPill(_params.trigger.table_name, 'string')}, Start Time: ${wfa.dataPill(_params.trigger.run_start_date_time, 'datetime')}`,
            }
        )

        // Test conditional logic based on request item
        wfa.flowLogic.if(
            {
                $id: Now.ID['test_service_catalog_if_request'],
                condition: `${wfa.dataPill(_params.trigger.request_item, 'string')}!=`,
                annotation: 'Check if request item exists',
            },
            () => {
                wfa.action(
                    action.core.log,
                    { $id: Now.ID['test_service_catalog_log_request'] },
                    {
                        log_level: 'info',
                        log_message: 'Processing service catalog request',
                    }
                )
            }
        )
    }
)

// Flow 2: Service Catalog trigger with foreground execution
export const testServiceCatalogTriggerForeground = Flow(
    {
        $id: Now.ID['test_service_catalog_trigger_foreground_flow'],
        name: 'Test Service Catalog Trigger - Foreground',
        description: 'Tests the Service Catalog trigger with foreground execution',
    },
    wfa.trigger(
        trigger.application.serviceCatalog,
        { $id: Now.ID['test_service_catalog_trigger_foreground'] },
        {
            run_flow_in: 'foreground',
        }
    ),
    (_params) => {
        // Log service catalog execution mode
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_service_catalog_log_foreground'] },
            {
                log_level: 'info',
                log_message: `Service Catalog (Foreground) - Request: ${wfa.dataPill(_params.trigger.request_item, 'string')}`,
            }
        )
    }
)
